    return next((i for i, s in enumerate(row_strips) if s[0] <= r < s[1]), -1)

def get_c_idx(c):
    return next((i for i, s in enumerate(col_strips) if s[0] <= c < s[1]), -1)

def region_colors(reg):
    rc = set()
    r_idx, c_idx = reg
    if r_idx < 0 or c_idx < 0:
        return rc
    for r in range(row_strips[r_idx][0], row_strips[r_idx][1]):
        for c in range(col_strips[c_idx][0], col_strips[c_idx][1]):
            v = test_input[r][c] if c < len(test_input[r]) else None
            if v not in (0, 8):
                rc.add(v)
    return rc

completion_regions = [(1,1), (1,3), (3,0), (3,2)]

for r_idx, c_idx in completion_regions:
    # Find the most common color among orthogonal neighbors
    r_start, r_end = row_strips[r_idx]
    c_start, c_end = col_strips[c_idx]

    center_r = (r_start + r_end) // 2
    center_c = (c_start + c_end) // 2

    # Count neighbor colors
    neighbor_colors = {}
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r_idx + dr, c_idx + dc
        if 0 <= nr < 4 and 0 <= nc < 4:
            nreg = (nr, nc)
            ncolors = region_colors(nreg)
            for c in ncolors:
                neighbor_colors[c] = neighbor_colors.get(c, 0) + 1

    # Choose most common color, default to 9 if no neighbors
    chosen_color = max(neighbor_colors.keys(), key=lambda x: neighbor_colors[x]) if neighbor_colors else 9
    print(f"Region ({r_idx},{c_idx}): using color {chosen_color} (count by neighbor: {neighbor_colors})")

