    # Copy from a similar existing region
    for r in range(r_start, r_end):
        for c in range(c_start, c_end):
            if output[r][c] == 0 and c < len(output[r]):
                # Don't overwrite if already filled, mark as completed
                pass  # Keep original 0s for now
            elif output[r][c] != 0 and output[r][c] != 9:
                # Change non-background, non-completed cells
                output[r][c] = 9  # Mark as completed area

